use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render(composed: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(composed.date.trim());
    out.push('\n');

    let overview = composed.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    let mut kept: Vec<&ItemVerdict> = composed.entries.iter().filter(|e| e.kept).collect();
    // Stable sort: most important first, original order otherwise preserved.
    kept.sort_by_key(|e| importance_rank(e.importance));

    if kept.is_empty() {
        out.push_str("\nNo items made the digest today.\n");
    } else {
        for (n, e) in kept.iter().enumerate() {
            out.push('\n');
            out.push_str(&(n + 1).to_string());
            out.push_str(". [");
            out.push_str(importance_label(e.importance));
            out.push_str(" / ");
            out.push_str(category_label(e.category));
            out.push_str("] ");
            out.push_str(e.title.trim());
            out.push('\n');

            let summary = e.summary.trim();
            if !summary.is_empty() {
                out.push_str("   ");
                out.push_str(summary);
                out.push('\n');
            }
            let link = e.link.trim();
            if !link.is_empty() {
                out.push_str("   ");
                out.push_str(link);
                out.push('\n');
            }
            let feed = e.feed.trim();
            if !feed.is_empty() {
                out.push_str("   via ");
                out.push_str(feed);
                out.push('\n');
            }
        }
    }

    out.push('\n');
    out.push_str(&kept.len().to_string());
    out.push_str(" selected of ");
    out.push_str(&composed.considered.len().to_string());
    out.push_str(" considered.\n");
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        // The notifier's own answer is reported as-is: `published` records
        // whether the channel accepted the digest, never a fabricated success.
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
